(()=>{const ENDPOINT='https://script.google.com/macros/s/AKfycbyKlCnPjHGmuMHbqf7rSVBjwQa5mpLnBOZfbpC4Y9mPMBpjsESlQAl-1nSvAwRg4L0_/exec';const jobs={'l1-support':['L1 Technical Support Engineer','Field Engineer \u00b7 Pan India \u00b7 10:00 AM\u20136:30 PM \u00b7 MON-SAT','We are looking for a proactive L1 Technical Support Engineer to provide first-level technical assistance and ensure smooth IT operations.',{sections:[['Key Responsibilities',['Provide first-level technical support for desktops, laptops, and IT hardware','Diagnose and resolve hardware, software, and network issues','Assist in installation, configuration, and setup of IT devices','Document user issues and escalate tickets as needed','Ensure excellent communication and high customer satisfaction','Willingness to travel for field engineer assignments']],['Requirements',['Minimum 1 year of hands-on technical support experience','Strong knowledge of basic hardware and software troubleshooting','Familiarity with network basics (preferred)','Strong communication and problem-solving skills']]]}],'hardware-support':['Technical Support Engineer (Hardware)','Mulund East, Mumbai \u00b7 10:00 AM\u20136:30 PM \u00b7 MON-SAT','We are seeking a skilled Technical Support Engineer (Hardware) to troubleshoot hardware issues, coordinate on-field tasks, and ensure seamless hardware operations.',{sections:[['Key Responsibilities',['Diagnose, troubleshoot, and resolve hardware issues for desktops, laptops, and IT devices','Perform root cause analysis to prevent recurring problems','Install and configure hardware products including PCs and laptops','Coordinate with on-field engineers to assign and monitor tasks','Maintain accurate records of hardware inventory and service history','Escalate unresolved issues to senior technical teams when necessary']],['Requirements',['1-2 years of experience in IT hardware support or related field','Hands-on experience with troubleshooting, installation, and configuration of hardware','Basic knowledge of L2-level processes is an advantage','Strong coordination, communication, and problem-solving skills']]]}],'vapt-intern':['Security Engineer \u2013 IT Infrastructure VAPT','Mulund East, Mumbai \u00b7 10:00 AM\u20136:30 PM \u00b7 MON-SAT','We are looking for a technically inclined Security Engineer to support IT Infrastructure Audit and Security Engineering initiatives.',{sections:[['Key Responsibilities',['Perform IT infrastructure security audits (servers, networks, endpoints, cloud)','Security architecture reviews and recommend improvements','Implement and validate system hardening across OS and network devices','Identify and manage vulnerabilities and misconfigurations','Analyze logs and alerts using SIEM tools','Review and validate firewall configurations and rules','Document audit findings, risks, and remediation recommendations','Support compliance assessments (ISO 27001, NIST, CIS benchmarks)']],['Requirements',['Understanding of security architecture fundamentals (defense-in-depth, zero trust)','Knowledge of system hardening techniques (Windows/Linux)','Familiarity with vulnerability management lifecycle','Basic automation/scripting skills (Python, Bash, or PowerShell preferred)','Understanding of networking fundamentals (TCP/IP, DNS, firewalls)','Basic awareness of cloud security concepts (AWS/Azure preferred)']],['Nice to Have',['CompTIA Security+, CISSP (awareness level)','Familiarity with Nessus, Qualys, Nmap, OpenVAS','Familiarity with cloud platforms (AWS, Azure)']]]}]};const M=document.getElementById('career-modal'),F=document.getElementById('career-form'),D=document.getElementById('career-details'),A=document.getElementById('career-application'),S=document.getElementById('career-status'),B=document.getElementById('career-submit');if(!M||!F)return;let opener;const close=()=>{M.hidden=true;document.body.classList.remove('career-modal-open');D.hidden=false;A.hidden=true;if(opener)opener.focus()};document.querySelectorAll('.career-open').forEach(b=>b.onclick=()=>{const j=jobs[b.dataset.job];if(!j)return;opener=b;document.getElementById('career-meta').textContent=j[1];document.getElementById('career-title').textContent=j[0];document.getElementById('career-summary').textContent=j[2];const list=document.getElementById('career-list');if(Array.isArray(j[3])){const ul=document.createElement('ul');j[3].forEach(t=>{const li=document.createElement('li');li.textContent=t;ul.append(li)});list.replaceChildren(ul)}else{list.replaceChildren(...j[3].sections.map(s=>{const section=document.createElement('section'),heading=document.createElement('h3'),ul=document.createElement('ul');heading.textContent=s[0];s[1].forEach(t=>{const li=document.createElement('li');li.textContent=t;ul.append(li)});section.append(heading,ul);return section}))}document.getElementById('career-apply-title').textContent='Apply: '+j[0];document.getElementById('career-job').value=j[0];M.hidden=false;document.body.classList.add('career-modal-open');M.querySelector('.career-panel').focus()});M.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!M.hidden)close()});document.getElementById('career-apply').onclick=()=>{D.hidden=true;A.hidden=false;F.elements.from_name.focus()};document.getElementById('career-back').onclick=()=>{A.hidden=true;D.hidden=false};F.addEventListener('submit',async e=>{e.preventDefault();if(!F.reportValidity())return;S.classList.remove('error');const file=F.elements.resume.files[0];if(file.size>4194304){S.textContent='Resume must be 4 MB or smaller.';S.classList.add('error');return}B.disabled=true;B.textContent='Submitting...';S.textContent='Uploading your application...';try{const b64=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(file)});const data=new URLSearchParams(new FormData(F));data.set('resume_base64',b64);data.set('resume_filename',file.name);data.set('resume_mimetype',file.type||'application/octet-stream');const response=await fetch(ENDPOINT,{method:'POST',mode:'no-cors',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:data.toString()});S.textContent='Your application was submitted. Thank you.';F.reset()}catch(err){S.textContent='We could not submit your application. Please email your resume and role title to info@itcraft.net.in.';S.classList.add('error')}finally{B.disabled=false;B.textContent='Submit application'}})})();